/**
 * The SPARQL the graph explorer generates in the browser (src/main/frontend/graph-explorer/rdf-vocabulary.ts and
 * graph-connection-discovery.ts) must run on a real RDF4J repository and return what the explorer expects. The queries
 * are committed under src/test/resources/graph-explorer-queries by {@code npm run fixtures:queries}; the Node test
 * query-fixtures-current.test.mjs keeps them in step with the generators.
 */
@TestInstance(TestInstance.Lifecycle.PER_CLASS)
class GraphExplorerQueryTest {

	private static final String FIXTURES = "/graph-explorer-queries/";

	private static final String DATA = """
			@prefix ex: <urn:ex:> .
			@prefix rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
			@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
			@prefix skos: <http://www.w3.org/2004/02/skos/core#> .
			@prefix xl: <http://www.w3.org/2008/05/skos-xl#> .
			ex:labelCode rdfs:subPropertyOf rdfs:label .
			ex:relation rdfs:label "is connected to"@en, "er knyttet til"@nb .
			ex:one ex:relation ex:two, ex:three, ex:four, ex:five; a ex:Thing; ex:labelCode "First resource"@en .
			ex:two ex:relation ex:one; a ex:Thing; skos:prefLabel "Second resource"@en .
			ex:three xl:prefLabel [xl:literalForm "Third resource"@en] .
			ex:propertyShape <http://www.w3.org/ns/shacl#path> ex:shapedPredicate; <http://www.w3.org/ns/shacl#name> "Shaped relationship"@en .
			ex:lexicalEntry <http://www.w3.org/ns/lemon/ontolex#canonicalForm> [<http://www.w3.org/ns/lemon/ontolex#writtenRep> "Lexical title"@en] .
			ex:Thing rdfs:label "Resource type"@en .
			ex:mentions rdfs:comment "Says that one resource mentions another"@en; rdfs:domain ex:Document; rdfs:range ex:Document .
			ex:six ex:mentions ex:seven .
			<< ex:six ex:mentions ex:seven ~ ex:claim >> ex:source ex:wiki .
			ex:six ex:mentions ex:seven {| ex:confidence 0.9 |} .
			ex:stmt a rdf:Statement; rdf:subject ex:six; rdf:predicate ex:mentions; rdf:object ex:seven; ex:by ex:alice .
			ex:alice ex:believes <<( ex:six ex:mentions ex:seven )>> .
			""";

	private Repository repository;

	@BeforeAll
	void loadFixtureData() throws IOException {
		repository = new SailRepository(new MemoryStore());
		repository.init();
		ValueFactory vf = repository.getValueFactory();
		try (RepositoryConnection connection = repository.getConnection()) {
			connection.add(new StringReader(DATA), "urn:ex:", RDFFormat.TURTLE);
			connection.add(vf.createIRI("urn:ex:named"), vf.createIRI("urn:ex:relation"), vf.createIRI("urn:ex:one"),
					vf.createIRI("urn:ex:graph"));
			connection.add(vf.createIRI("urn:ex:named"), vf.createIRI("http://www.w3.org/2000/01/rdf-schema#label"),
					vf.createLiteral("Named resource", "en"), vf.createIRI("urn:ex:graph"));
		}
	}

	@AfterAll
	void shutDown() {
		repository.shutDown();
	}

	Stream<Arguments> generatedQueries() throws IOException {
		Properties expected = new Properties();
		try (InputStream counts = GraphExplorerQueryTest.class
				.getResourceAsStream(FIXTURES + "expected-counts.properties")) {
			assertThat(counts).as("run `npm run fixtures:queries` in tools/workbench").isNotNull();
			expected.load(counts);
		}
		return expected.stringPropertyNames()
				.stream()
				.sorted()
				.map(name -> Arguments.of(name, Integer.parseInt(expected.getProperty(name).trim())));
	}

	@ParameterizedTest(name = "{0} returns {1} rows")
	@MethodSource("generatedQueries")
	void generatedQueryRunsOnRdf4jAndReturnsTheExpectedRows(String name, int expectedRows) throws IOException {
		String query = fixture(name + ".rq");
		int rows = 0;
		try (RepositoryConnection connection = repository.getConnection();
				TupleQueryResult result = connection.prepareTupleQuery(QueryLanguage.SPARQL, query).evaluate()) {
			while (result.hasNext()) {
				BindingSet row = result.next();
				rows++;
				if (name.startsWith("neighbors")) {
					assertThat(row.getValue("selected")).as("per-node result key of %s", name).isNotNull();
				}
			}
		}
		assertThat(rows).as(name).isEqualTo(expectedRows);
	}

	@Test
	void linkCountsLeaveOutTypesAndValuesAndStopAtTheCap() throws IOException {
		// ex:one links to two, three, four and five and is linked from two and (in a named graph) from named; its type
		// and its label are not links. ex:Thing is only a type, so it has no links and no row.
		assertThat(linkCounts("links.rq")).containsExactlyInAnyOrderEntriesOf(Map.of("urn:ex:one", 6, "urn:ex:two", 2));
		// Counting stops one past the cap: "more than 3".
		assertThat(linkCounts("links-capped.rq")).containsExactlyInAnyOrderEntriesOf(
				Map.of("urn:ex:one", 4, "urn:ex:two", 2));
	}

	@Test
	void theGraphExportIsTurtleThatRioReadsBackStatementForStatement() throws IOException {
		Model model = Rio.parse(new StringReader(fixture("graph-export.ttl")), "", RDFFormat.TURTLE);
		ValueFactory vf = SimpleValueFactory.getInstance();
		IRI alice = vf.createIRI("http://example.org/alice");
		assertThat(model).hasSize(10);
		assertThat(model.filter(vf.createIRI("http://example.org/claim"), RDF.REIFIES, null).objects())
				.containsExactly(vf.createTripleTerm(alice, vf.createIRI("http://schema.org/knows"),
						vf.createIRI("http://example.org/bob")));
		assertThat(model.contains(alice, RDFS.LABEL, vf.createLiteral("Alice \"Al\" Smith", "en"))).isTrue();
		assertThat(model.contains(alice, RDFS.LABEL, vf.createLiteral("line\nbreak"))).isTrue();
		assertThat(model.contains(alice, vf.createIRI("http://schema.org/age"), vf.createLiteral("39", XSD.INTEGER)))
				.isTrue();
		assertThat(model.contains(alice, vf.createIRI("http://example.org/odd#name."), vf.createLiteral("x"))).isTrue();
		assertThat(model.filter(null, vf.createIRI("http://schema.org/worksFor"), null).objects())
				.containsExactly(vf.createIRI("http://example.org/acme%20corp"));
	}

	@Test
	void statementAnnotationsFindReifiersReificationsAndReferences() throws IOException {
		// ex:claim (named with ~) and the annotation's blank node reify the statement, ex:stmt is a classic
		// rdf:Statement about it, and ex:alice refers to the triple term directly.
		assertThat(annotationRows("statement-annotations.rq")).containsExactlyInAnyOrder(
				"reifier urn:ex:claim urn:ex:source urn:ex:wiki",
				"reifier _ urn:ex:confidence 0.9",
				"reification urn:ex:stmt urn:ex:by urn:ex:alice",
				"reference urn:ex:alice urn:ex:believes -");
		// Stores without triple terms still find classic reifications.
		assertThat(annotationRows("statement-annotations-classic.rq")).containsExactly(
				"reification urn:ex:stmt urn:ex:by urn:ex:alice");
	}

	@Test
	void linkCountsSkipTripleTermsAndCountAStatementOnceInEveryScope() throws IOException {
		// ex:claim's rdf:reifies and ex:alice's ex:believes point at triple terms, which the canvas never draws; what
		// is left is ex:claim ex:source ex:wiki and ex:stmt ex:by ex:alice.
		assertThat(linkCounts("links-triple-terms.rq")).containsExactlyInAnyOrderEntriesOf(
				Map.of("urn:ex:claim", 1, "urn:ex:alice", 1));
		// The "all graphs" scope reads the default graph and every named graph; ex:named ex:relation ex:one (in
		// urn:ex:graph) is still one link.
		assertThat(linkCounts("links-all-graphs.rq")).containsExactlyEntriesOf(Map.of("urn:ex:one", 6));
		try (RepositoryConnection connection = repository.getConnection();
				TupleQueryResult result = connection
						.prepareTupleQuery(QueryLanguage.SPARQL, fixture("predicate-usage-all-graphs.rq"))
						.evaluate()) {
			// ex:relation: one -> two, three, four, five; two -> one; named -> one.
			assertThat(result.next().getValue("uses").stringValue()).isEqualTo("6");
		}
	}

	private List<String> annotationRows(String file) throws IOException {
		List<String> rows = new ArrayList<>();
		try (RepositoryConnection connection = repository.getConnection();
				TupleQueryResult result = connection.prepareTupleQuery(QueryLanguage.SPARQL, fixture(file))
						.evaluate()) {
			while (result.hasNext()) {
				BindingSet row = result.next();
				Value about = row.getValue("about");
				Value value = row.getValue("value");
				rows.add(row.getValue("kind").stringValue() + " " + (about.isBNode() ? "_" : about.stringValue()) + " "
						+ row.getValue("property").stringValue() + " " + (value == null ? "-" : value.stringValue()));
			}
		}
		return rows;
	}

	private Map<String, Integer> linkCounts(String file) throws IOException {
		Map<String, Integer> counts = new HashMap<>();
		try (RepositoryConnection connection = repository.getConnection();
				TupleQueryResult result = connection.prepareTupleQuery(QueryLanguage.SPARQL, fixture(file))
						.evaluate()) {
			while (result.hasNext()) {
				BindingSet row = result.next();
				counts.put(row.getValue("selected").stringValue(),
						Integer.parseInt(row.getValue("links").stringValue()));
			}
		}
		return counts;
	}

	private static String fixture(String file) throws IOException {
		try (InputStream in = GraphExplorerQueryTest.class.getResourceAsStream(FIXTURES + file)) {
			assertThat(in).as(file).isNotNull();
			return new String(in.readAllBytes(), StandardCharsets.UTF_8);
		}
	}
}
